-- TomoModForever 1.2.6 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_126_slash"] = "Changed - The main command is now /tmf (TomoMod Forever's initials). /tm and /tomomod still work.",
    ["wn_126_dquests"] = "New - Dungeon codex, Quests tab: each dungeon quest now says where it starts (giver, zone and coordinates, or the item that starts it), who to turn it in to, and the quests to do first, ticked when done. A quest whose chain is not done is marked \"Needs: ...\". Click a quest for a waypoint to its giver, or to the first quest of its chain still to do. Elite quests too: a quest whose chain has a step in your quest log shows \"Chain in progress: step n of m\".",
    ["wn_126_levels"] = "Fixed - World map: zone level ranges now really show when hovering a zone (1.2.5 read the wrong field of the map label). /tmf maplevels lists the levels of the zones of the open map.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_126_slash"] = "Modifié - La commande principale devient /tmf (les initiales de TomoMod Forever). /tm et /tomomod marchent toujours.",
    ["wn_126_dquests"] = "Nouveau - Codex des donjons, onglet Quêtes : chaque quête de donjon indique où elle commence (donneur, zone et coordonnées, ou l'objet qui la lance), à qui la rendre, et les quêtes à faire avant, cochées quand elles sont faites. Une quête dont la chaîne n'est pas faite est marquée « Prérequis : ... ». Clique sur une quête pour poser un point de route vers son donneur, ou vers la première quête de sa chaîne qui reste à faire. Les quêtes élites aussi : une quête dont une étape de la chaîne est dans ton journal affiche « Chaîne en cours : étape n sur m ».",
    ["wn_126_levels"] = "Corrigé - Carte du monde : les tranches de niveaux s'affichent maintenant vraiment au survol d'une zone (la 1.2.5 lisait le mauvais champ de l'étiquette de la carte). /tmf niveaux liste les niveaux des zones de la carte ouverte.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_126_slash"] = "Geändert - Der Hauptbefehl ist jetzt /tmf (die Initialen von TomoMod Forever). /tm und /tomomod funktionieren weiterhin.",
    ["wn_126_dquests"] = "Neu - Dungeon-Kodex, Reiter Quests: Jede Dungeonquest zeigt jetzt, wo sie beginnt (Questgeber, Gebiet und Koordinaten oder der Gegenstand, der sie startet), wo man sie abgibt und welche Quests vorher nötig sind, abgehakt wenn erledigt. Eine Quest mit offener Kette ist als „Voraussetzung: ...“ markiert. Klicke auf eine Quest für einen Wegpunkt zum Questgeber oder zur ersten offenen Quest der Kette. Auch Elitequests: Eine Quest, deren Kette einen Schritt in deinem Questlog hat, zeigt „Kette läuft: Schritt n von m“.",
    ["wn_126_levels"] = "Behoben - Weltkarte: Die Stufenspannen der Gebiete erscheinen jetzt wirklich beim Zeigen auf ein Gebiet (1.2.5 las das falsche Feld der Kartenbeschriftung). /tmf maplevels listet die Stufen der Gebiete der offenen Karte.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_126_slash"] = "Cambiado - El comando principal pasa a ser /tmf (las iniciales de TomoMod Forever). /tm y /tomomod siguen funcionando.",
    ["wn_126_dquests"] = "Nuevo - Códice de mazmorras, pestaña Misiones: cada misión de mazmorra indica dónde empieza (quién la da, zona y coordenadas, o el objeto que la inicia), a quién entregarla y las misiones previas, marcadas al completarlas. Una misión con la cadena sin hacer aparece como «Requisito: ...». Haz clic en una misión para poner un punto de ruta hacia quien la da o hacia la primera misión pendiente de su cadena. También las misiones de élite: una misión con un paso de su cadena en tu registro muestra «Cadena en curso: paso n de m».",
    ["wn_126_levels"] = "Corregido - Mapa del mundo: los rangos de nivel de las zonas ahora sí aparecen al pasar sobre una zona (la 1.2.5 leía el campo equivocado de la etiqueta del mapa). /tmf maplevels muestra los niveles de las zonas del mapa abierto.",
})

